async def act(page):
    """
    From the current "New Rule / Magento Admin" page, ensure the rule applies to all customer groups,
    set the action to a fixed $15 discount, and save the rule.

    Knowledge-base functions: none are provided in the environment, so none are used.
    """
    # Wait until DOM is ready
    await page.wait_for_load_state("domcontentloaded")

    # Explicit reasoning about knowledge-base functions: there are no helper functions available in the
    # provided knowledge base for interacting with this page, so all actions are done directly with Playwright.

    # 1) Ensure all customer groups are selected so the rule applies to all customers.
    try:
        customer_groups = page.get_by_role("listbox", name="Customer Groups *")
        if await customer_groups.count() > 0:
            await customer_groups.first.select_option([
                {"label": "NOT LOGGED IN"},
                {"label": "General"},
                {"label": "Wholesale"},
                {"label": "VIP Member"},
                {"label": "Private Sales Member"},
            ])
            await page.wait_for_timeout(200)
    except Exception:
        # Fallback: try any listbox and attempt to select known labels
        try:
            all_listboxes = page.get_by_role("listbox")
            for i in range(await all_listboxes.count()):
                lb = all_listboxes.nth(i)
                try:
                    await lb.select_option([
                        {"label": "NOT LOGGED IN"},
                        {"label": "General"},
                        {"label": "Wholesale"},
                        {"label": "VIP Member"},
                        {"label": "Private Sales Member"},
                    ])
                except Exception:
                    continue
        except Exception:
            pass

    # 2) Open the Actions tab to reveal action-related controls (if not already active)
    try:
        actions_tab = page.get_by_role("link", name="Actions")
        if await actions_tab.count() > 0:
            await actions_tab.first.click()
            await page.wait_for_timeout(300)
    except Exception:
        # if unable to click, continue: controls may already be visible
        pass

    # Helper to try multiple combobox names and multiple option labels
    async def try_select_combobox(names, option_labels):
        for n in names:
            try:
                combo = page.get_by_role("combobox", name=n)
                if await combo.count() > 0:
                    # try each label until one succeeds
                    for lbl in option_labels:
                        try:
                            await combo.first.select_option({"label": lbl})
                            return True
                        except Exception:
                            continue
            except Exception:
                continue
        return False

    # 3) Set Apply / Action to Fixed amount discount. Try several plausible names and labels.
    await try_select_combobox([
        "Apply", "Apply *", "Action", "Apply To", "Apply the rule"
    ], ["Fixed amount discount", "Fixed Amount Discount", "Fixed"])

    # 4) Fill Discount Amount = 15. Try spinbutton then textbox with several possible names.
    filled = False
    discount_names = ["Discount Amount", "Discount Amount *", "Discount", "Discount Amount (Fixed)"]
    for n in discount_names:
        try:
            spin = page.get_by_role("spinbutton", name=n)
            if await spin.count() > 0:
                await spin.first.fill("15")
                filled = True
                break
        except Exception:
            pass
        try:
            txt = page.get_by_role("textbox", name=n)
            if await txt.count() > 0:
                await txt.first.fill("15")
                filled = True
                break
        except Exception:
            pass

    # Additional fallback: any spinbutton or textbox that looks numeric
    if not filled:
        try:
            all_spins = page.get_by_role("spinbutton")
            if await all_spins.count() > 0:
                await all_spins.first.fill("15")
                filled = True
        except Exception:
            pass
    if not filled:
        try:
            all_texts = page.get_by_role("textbox")
            # attempt to fill first visible textbox that is empty or likely the discount
            for i in range(await all_texts.count()):
                t = all_texts.nth(i)
                try:
                    await t.fill("15")
                    filled = True
                    break
                except Exception:
                    continue
        except Exception:
            pass

    await page.wait_for_timeout(200)

    # 5) Save the rule. This navigates away, so do this as the last action.
    try:
        # The Save button is directly under the document in the accessibility tree
        save_btn = page.get_by_role("button", name="Save")
        if await save_btn.count() > 0:
            await save_btn.first.click()
            return
    except Exception:
        pass

    # fallback: Save and Continue Edit
    try:
        save_continue = page.get_by_role("button", name="Save and Continue Edit")
        if await save_continue.count() > 0:
            await save_continue.first.click()
            return
    except Exception:
        pass

    # If we couldn't find a Save control, end without navigation
    return

